def _get(name: str) -> List[float]:
    for n, v in EXPECTED:
        if n == name:
            return v
    raise ValueError("missing " + name)

def check(name: str, got, rtol: float = 1e-6, atol: float = 1e-12):
    want = _get(name)
    g = List[float]()
    for v in got:
        if isinstance(v, np.ndarray):
            for w in v.ravel():
                g.append(float(w))
        else:
            g.append(float(v))
    ok = len(g) == len(want)
    if ok:
        for i in range(len(want)):
            if abs(g[i] - want[i]) > atol + rtol * abs(want[i]):
                ok = False
    if not ok:
        print("TEST FAILED:", name, g, want)

def make_raw():
    rng = np.random.RandomState(0)
    sf = 100.
    n = 2000
    t = np.arange(n) / sf
    s1 = np.sin(2 * np.pi * 1.3 * t)
    s2 = np.sign(np.sin(2 * np.pi * 0.7 * t))
    s3 = rng.laplace(size=n)
    blink = np.zeros(n)
    for c in [300, 800, 1300, 1700]:
        blink += 5 * np.exp(-0.5 * ((np.arange(n) - c) / 8.) ** 2)
    S = np.vstack([s1, s2, s3, blink])
    A = rng.randn(5, 4)
    X = A @ S + 0.01 * rng.randn(5, n)
    eog = blink + 0.05 * rng.randn(n)
    data = np.vstack([X, eog.reshape((1, n))]) * 1e-5
    info = mne.create_info(['E1', 'E2', 'E3', 'E4', 'E5', 'EOG'], sf, ['eeg'] * 5 + ['eog'])
    return mne.io.RawArray(data, info)

raw = make_raw()
specs = [("po", True, True, "tanh"), ("pstd", False, False, "tanh"), ("pext", False, True, "tanh"),
         ("pexp", True, True, "exp"), ("pcube", False, False, "cube")]
for name, ortho, ext, fun in specs:
    fp = {"ortho": 1.0 if ortho else 0.0, "extended": 1.0 if ext else 0.0}
    ica = ICA(n_components=4, random_state=42, method="picard", fit_params=fp, max_iter=300, picard_fun=fun)
    ica.fit(raw)
    check(name + "_meta", [float(ica.n_iter_), float(ica.n_components_)])
    check(name + "_unmixing", ica.unmixing_matrix_, 1e-4, 1e-7)
    if name == "po":
        check("po_sources", ica.get_sources(raw).get_data()[:, :5], 1e-4, 1e-7)
        ev = ica.get_explained_variance_ratio(raw)
        check("po_evr", [ev["eeg"]], 1e-6, 1e-9)
        ev1 = ica.get_explained_variance_ratio(raw, components=[1, 2])
        check("po_evr12", [ev1["eeg"]], 1e-6, 1e-9)
        check("po_score", ica.score_sources(raw, target="EOG"), 1e-5, 1e-8)
